        {
            Game=Fresh(m,health);Pair=new(m.CircleSounds!.Timing,false);
            Game.GlobalSoundTiming+=t=>{Trace.Add("Clock");Pair.M.Clock(t);};
            Game.ContinuingSound+=(s,t,active)=>{Trace.Add((active?"Continue":"Pause")+":"+s.Audio.Index);Obs(new{time=t,active,audio=s.Audio.Index,processed=s.ProcessedCheckpoints,success=s.SuccessfulCheckpoints,failed=s.FailedCheckpoints,head=s.Head.Result,parent=s.Result,ledger=Game.Ledger.LastEvent});if(active){var d=Data(s.Definition);Pair.M.Submit(d.RawSound,d.BaseSet,d.AdditionSet,false,s.PresentationBallX);}else Pair.M.QueuePause();};
